// Hides: the header every generated file opens with: the
// generator's name and the SHA-256 of the text under the header, so a hand edit no longer matches
// and the check fails (scripts/check/generated.mjs).
import { createHash } from 'node:crypto'

const HEADER = /^\/\/ Generated by (\S+), sha256 ([0-9a-f]{64})\. Do not edit\.\n/

/** @param {string} text */
const sha256 = text => createHash('sha256').update(text).digest('hex')

/**
 * A generated file's text: the header, then `body`.
 * @param {string} generator the generator's path from the project root
 * @param {string} body
 */
export const generated = (generator, body) =>
  `// Generated by ${generator}, sha256 ${sha256(body)}. Do not edit.\n${body}`

/**
 * Whether a generated file's text is as its generator wrote it: its header names a generator and
 * the hash of what follows. Null when it is; else what is wrong.
 * @param {string} text
 * @returns {string | null}
 */
export function generatedFault(text) {
  const head = HEADER.exec(text)
  if (!head) return 'has no "// Generated by <script>, sha256 <hash>. Do not edit." header'
  return sha256(text.slice(head[0].length)) === head[2]
    ? null
    : `was edited after ${head[1]} wrote it`
}
